 if(word==='cookies')art='<ellipse cx="150" cy="183" rx="108" ry="34" fill="#c9d8c8"/><g fill="#dab06d" stroke="#be9254" stroke-width="3"><ellipse cx="100" cy="140" rx="43" ry="38"/><ellipse cx="183" cy="132" rx="43" ry="38"/><ellipse cx="145" cy="170" rx="43" ry="38"/></g><g fill="#78583b">'+[[80,129],[109,145],[92,156],[121,125],[160,120],[184,143],[201,117],[164,151],[128,166],[151,183],[167,165],[140,148]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5"/>`).join('')+'</g>';
