const SAFE_DISTRACTORS=['airplane','alligator','acorn','boat','banana','bus','car','cake','cup','duck','door','doll','eagle','elf','feather','fan','flower','gift','garden','guitar','house','hammer','horse','igloo','insect','ink','jacket','jam','jet','kite','king','key','lion','lamp','leaf','moon','map','mouse','nest','net','nail','orange','owl','octopus','pencil','pear','pig','queen','quilt','robot','rainbow','ring','sun','sock','sand','tree','train','tiger','umbrella','van','wagon','xylophone','yoyo','zebra'];
export function reviewChoices(word,random=Math.random){const item=VOCABULARY[word];if(!item)throw Error('Unknown vocabulary word');const safe=w=>w&&!VOCABULARY[w]&&w!==word;const first=[item.sameStart,...SAFE_DISTRACTORS].find(w=>safe(w)&&w[0]===word[0]);const others=[...new Set([...(item.others||[]),...SAFE_DISTRACTORS])].filter(w=>safe(w)&&w[0]!==word[0]).slice(0,2);return shuffled([word,first,...others],random);}
export function rememberWord(state,word,now=new Date().toISOString(),sourceGame){if(!VOCABULARY[word])return null;state.vocabulary??={};const previous=state.vocabulary[word];const entry={word,picture:word,status:'learnt',remembered:true,markedBy:'child',firstSavedAt:previous?.firstSavedAt||now,lastSavedAt:now,savedCount:(previous?.savedCount||0)+1,sourceGame:sourceGame||VOCABULARY[word].sourceGame||'Letter Garden Vocabulary'};state.vocabulary[word]=entry;state.pendingWordSaves=(state.pendingWordSaves||[]).filter(w=>w!==word);return entry;}
export function saveWordSet(state,title,words,now=new Date().toISOString()){const valid=[...new Set(words)].filter(word=>state.vocabulary?.[word]&&VOCABULARY[word]);const name=title.trim().slice(0,60);if(!name||!valid.length)throw Error('Name the set and choose at least one saved word.');state.vocabularySets??=[];const old=state.vocabularySets.find(s=>s.title===name);const set={id:old?.id||'words-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),title:name,words:valid,createdAt:old?.createdAt||now,updatedAt:now};state.vocabularySets=state.vocabularySets.filter(s=>s.id!==set.id).concat(set).slice(-50);return set;}
